operation.add:
$data['variant_identifier_mappings'] = array();
if (!class_exists('CyberpunksShopVariantIdentifiersStorage') && is_file(DIR_SYSTEM . 'library/cyberpunks_shop_variant_identifiers_storage.php')) {
	require_once(DIR_SYSTEM . 'library/cyberpunks_shop_variant_identifiers_storage.php');
}
if (class_exists('CyberpunksShopVariantIdentifiersStorage')) {
	$vi_all = $this->config->get('module_cyberpunks_variant_identifiers_mappings');
	if (!is_array($vi_all) || !$vi_all) {
		$vi_all = CyberpunksShopVariantIdentifiersStorage::loadAll($this->registry);
	}
	if (is_array($vi_all)) {
		$vi_pid = (int)$this->request->get['product_id'];
		foreach ($vi_all as $vi_row) {
			if (!is_array($vi_row)) {
				continue;
			}
			$vi_status = isset($vi_row['t']) ? $vi_row['t'] : (isset($vi_row['status']) ? $vi_row['status'] : 1);
			if (empty($vi_status)) {
				continue;
			}
			$row_pid = isset($vi_row['p']) ? (int)$vi_row['p'] : (isset($vi_row['product_id']) ? (int)$vi_row['product_id'] : 0);
			if ($row_pid !== $vi_pid) {
				continue;
			}
			$vi_sku = isset($vi_row['k']) ? trim((string)$vi_row['k']) : (isset($vi_row['sku']) ? trim((string)$vi_row['sku']) : '');
			$vi_gtin = isset($vi_row['g']) ? trim((string)$vi_row['g']) : (isset($vi_row['gtin']) ? trim((string)$vi_row['gtin']) : '');
			$vi_sig = isset($vi_row['s']) ? trim((string)$vi_row['s']) : (isset($vi_row['option_value_signature']) ? trim((string)$vi_row['option_value_signature']) : '');
			if ($vi_sig === '' || ($vi_sku === '' && $vi_gtin === '')) {
				continue;
			}
			$data['variant_identifier_mappings'][] = array(
				's' => $vi_sig,
				'k' => $vi_sku,
				'g' => $vi_gtin
			);
		}
	}
}

$variant_sku = '';
				$variant_gtin = '';
				$variant_id_match = CyberpunksShopVariantIdentifiersStorage::resolveCartIdentifiers(
					is_array($this->config->get('module_cyberpunks_variant_identifiers_mappings')) ? $this->config->get('module_cyberpunks_variant_identifiers_mappings') : array(),
					(int)$product['product_id'],
					isset($product['option']) && is_array($product['option']) ? $product['option'] : array()
				);
				if (!empty($variant_id_match['sku'])) {
					$variant_sku = (string)$variant_id_match['sku'];
				}
				if (!empty($variant_id_match['gtin'])) {
					$variant_gtin = (string)$variant_id_match['gtin'];
				}

{% if cyberpunks_variant_identifiers_import_action %}
<form id="cyberpunks-vi-import-form" action="{{ cyberpunks_variant_identifiers_import_action }}" method="post" enctype="multipart/form-data" style="display:none;"></form>
{% endif %}
